<?php require 'config.php'; if(!isset($_SESSION['user'])){header('Location:login.php');exit;} $defaults=['site_title'=>'Adventure AVV','subtitle'=>'Я джуниор веб-разработчик и начинающий 3D-художник','about'=>'Мне нравится искусство, путешествия и 3D-графика. Я делаю этот сайт как личный проект.','contacts'=>'Email: avvspirit@gmail.com']; foreach($defaults as $k=>$v){$pdo->prepare('INSERT IGNORE INTO content (content_key,content_value) VALUES (?,?)')->execute([$k,$v]);} if($_SERVER['REQUEST_METHOD']==='POST'){ foreach($defaults as $k=>$_){ if(isset($_POST[$k])){$pdo->prepare('UPDATE content SET content_value=? WHERE content_key=?')->execute([$_POST[$k],$k]);}} $saved=true;} $map=$pdo->query('SELECT content_key,content_value FROM content')->fetchAll(); $data=[]; foreach($map as $r){$data[$r['content_key']]=$r['content_value'];} ?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Тексты сайта</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="style.css"></head><body><?php include 'navbar.php'; ?><div class="container mt-4 fade-in"><h2 class="mb-3">Редактирование текстов</h2><?php if(!empty($saved)):?><div class="alert alert-success">Сохранено</div><?php endif; ?><form method="post" class="row g-3"><div class="col-12"><label class="form-label">Заголовок (site_title)</label><input name="site_title" class="form-control" value="<?= htmlspecialchars($data['site_title']??'') ?>"></div><div class="col-12"><label class="form-label">Подзаголовок (subtitle)</label><input name="subtitle" class="form-control" value="<?= htmlspecialchars($data['subtitle']??'') ?>"></div><div class="col-12"><label class="form-label">Обо мне (about)</label><textarea name="about" rows="4" class="form-control"><?= htmlspecialchars($data['about']??'') ?></textarea></div><div class="col-12"><label class="form-label">Контакты (contacts)</label><textarea name="contacts" rows="3" class="form-control"><?= htmlspecialchars($data['contacts']??'') ?></textarea></div><div class="col-12"><button class="btn btn-primary">Сохранить</button></div></form></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>